shellCommands.command:
rm -rf dist && cat > src/smoke.test.tsx <<'EOF'
import {describe, expect, it} from 'vitest';
import {renderToString} from 'react-dom/server';
import {ThemeProvider} from '@gravity-ui/uikit';
import {App} from './App';

describe('smoke', () => {
  it('renders dashboard with grouped order table', () => {
    const html = renderToString(<ThemeProvider theme="light"><App /></ThemeProvider>);
    expect(html).toContain('Главная');
    expect(html).toContain('Пользователи');
    expect(html).toContain('Всего заказов');
    expect(html).toContain('Выбрано: 0');
    expect(html).toContain('ORD-');
    expect(html).toContain('В обработке');
    console.log('HTML length', html.length, 'group titles:', ['Новый','В обработке','Отправлен','Доставлен','Отменён'].map(t => `${t}=${html.split(t).length-1}`).join(' '));
  });
});
EOF
timeout 180000 npx vitest run src/smoke.test.tsx 2>&1 | tail -40; rm -f src/smoke.test.tsx; ls src

cat > vitest.smoke.config.mjs <<'EOF'
