const html = renderToString(<ThemeProvider theme="light"><App /></ThemeProvider>);
const count = (t: string) => html.split(t).length - 1;
console.log('length', html.length);
console.log('nav:', ['Главная', 'Пользователи', 'Заказы', 'Настройки'].map((t) => `${t}=${count(t)}`).join(' '));
